def solve_math_problem(lower_bound: int, upper_bound: int) -> Optional[int]:
    """
    Finds the largest integer n such that n(n+1)(n+2)(n+3) = k,
    where k is one of {n, n+1, n+2, n+3}.
    """
    solutions = set()

    # The equation is n(n+1)(n+2)(n+3) = k
    # Case 1: n(n+1)(n+2)(n+3) = n
    # Case 2: n(n+1)(n+2)(n+3) = n+1
    # Case 3: n(n+1)(n+2)(n+3) = n+2
    # Case 4: n(n+1)(n+2)(n+3) = n+3

    for n in range(lower_bound, upper_bound + 1):
        product = n * (n + 1) * (n + 2) * (n + 3)
        targets = {n, n + 1, n + 2, n + 3}

        if product in targets:
            solutions.add(max(n, n + 1, n + 2, n + 3))

    if not solutions:
        return None

    return max(solutions)

